//! Caller-supplied identifiers for project entities (tracks, clips, assets, folders).
//!
//! IDs are chosen by the caller (explicit IDs make batch scripts reproducible) or
//! generated by the core. They appear in semantic targets such as `clip:<id>` and
//! `trim:<clip>:start`, so the alphabet excludes `:`, whitespace and control bytes.

use std::borrow::Borrow;
use std::collections::HashSet;
use std::fmt;
use std::ops::Deref;
use std::sync::{Mutex, OnceLock};

pub const MAX_ID_LEN: usize = 64;

/// A validated, interned identifier.
///
/// WHY interned and `Copy`: the editor state hands IDs to closures, selections and
/// gesture handlers by value, and the original prototype used `&'static str` for
/// them. Interning keeps that cheap ownership model while letting callers create IDs
/// at run time. Trade-off accepted and documented in `docs/core-architecture.md`:
/// an interned string lives until the process ends, so the memory bound is the
/// number of *distinct* IDs ever created, not the number of live entities.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Id(&'static str);

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum IdError {
    Empty,
    TooLong(usize),
    InvalidChar(char),
}

impl fmt::Display for IdError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Empty => write!(f, "an ID cannot be empty"),
            Self::TooLong(len) => write!(f, "an ID has at most {MAX_ID_LEN} bytes, got {len}"),
            Self::InvalidChar(ch) => write!(
                f,
                "`{ch}` is not allowed in an ID (use letters, digits, `-`, `_` or `.`)"
            ),
        }
    }
}

impl std::error::Error for IdError {}

fn interner() -> &'static Mutex<HashSet<&'static str>> {
    static INTERNER: OnceLock<Mutex<HashSet<&'static str>>> = OnceLock::new();
    INTERNER.get_or_init(|| Mutex::new(HashSet::new()))
}

impl Id {
    /// Checks `raw` against the alphabet and length rules without interning it, so a request
    /// that is going to be refused never grows the interner (F017 validates before it commits).
    pub fn validate(raw: &str) -> Result<(), IdError> {
        if raw.is_empty() {
            return Err(IdError::Empty);
        }
        if raw.len() > MAX_ID_LEN {
            return Err(IdError::TooLong(raw.len()));
        }
        if let Some(ch) = raw
            .chars()
            .find(|ch| !(ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.')))
        {
            return Err(IdError::InvalidChar(ch));
        }
        Ok(())
    }

    /// Validates and interns `raw`.
    pub fn new(raw: &str) -> Result<Self, IdError> {
        Self::validate(raw)?;
        let mut set = interner()
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        if let Some(existing) = set.get(raw) {
            return Ok(Self(existing));
        }
        let leaked: &'static str = Box::leak(raw.to_string().into_boxed_str());
        set.insert(leaked);
        Ok(Self(leaked))
    }

    /// For compile-time literals in demo bootstrap and tests. Panics on an invalid
    /// literal, which is a programming error, never caller input.
    pub fn lit(raw: &str) -> Self {
        match Self::new(raw) {
            Ok(id) => id,
            Err(error) => panic!("invalid ID literal `{raw}`: {error}"),
        }
    }

    pub fn as_str(self) -> &'static str {
        self.0
    }

    /// Number of distinct IDs interned so far (diagnostics for the documented trade-off).
    pub fn interned_count() -> usize {
        interner()
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .len()
    }
}

impl Deref for Id {
    type Target = str;
    fn deref(&self) -> &str {
        self.0
    }
}

impl AsRef<str> for Id {
    fn as_ref(&self) -> &str {
        self.0
    }
}

impl Borrow<str> for Id {
    fn borrow(&self) -> &str {
        self.0
    }
}

impl fmt::Display for Id {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.0)
    }
}

impl fmt::Debug for Id {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self.0, f)
    }
}

impl PartialEq<str> for Id {
    fn eq(&self, other: &str) -> bool {
        self.0 == other
    }
}

impl PartialEq<&str> for Id {
    fn eq(&self, other: &&str) -> bool {
        self.0 == *other
    }
}

impl PartialEq<Id> for &str {
    fn eq(&self, other: &Id) -> bool {
        *self == other.0
    }
}

impl PartialEq<Id> for str {
    fn eq(&self, other: &Id) -> bool {
        self == other.0
    }
}

impl serde::Serialize for Id {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.0)
    }
}

impl From<Id> for serde_json::Value {
    fn from(id: Id) -> Self {
        serde_json::Value::String(id.0.to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn validates_the_alphabet_and_length() {
        assert!(Id::new("clip-1.a_b").is_ok());
        assert_eq!(Id::new(""), Err(IdError::Empty));
        assert_eq!(Id::new("a:b"), Err(IdError::InvalidChar(':')));
        assert_eq!(Id::new("a b"), Err(IdError::InvalidChar(' ')));
        assert!(matches!(
            Id::new(&"x".repeat(65)),
            Err(IdError::TooLong(65))
        ));
    }

    #[test]
    fn validate_answers_like_new_without_interning() {
        for raw in ["", "a:b", "a b", &"x".repeat(65), "ok-1.a_b"] {
            assert_eq!(Id::validate(raw), Id::new(raw).map(|_| ()), "{raw:?}");
        }
        // Validating alone never reaches the interner.
        let raw = "never-interned-by-validate-only";
        assert!(Id::validate(raw).is_ok());
        assert!(
            !interner()
                .lock()
                .unwrap_or_else(|poison| poison.into_inner())
                .contains(raw)
        );
    }

    #[test]
    fn equal_ids_share_one_interned_string() {
        let a = Id::new("shared-id").unwrap();
        let b = Id::new("shared-id").unwrap();
        assert_eq!(a, b);
        // One allocation for both. (The global interned count is not asserted: other tests
        // intern ids in parallel, which made a before/after comparison flaky.)
        assert!(std::ptr::eq(a.as_str(), b.as_str()));
        assert_eq!(a, "shared-id");
    }
}
